import decimal

def money_round(x):
    if isinstance(x, str):
        d = decimal.Decimal(x)
    else:
        d = decimal.Decimal(str(x))
    return float(d.quantize(decimal.Decimal('0.01'), rounding=decimal.ROUND_HALF_UP))
